#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 10
static int parent[MAXN];
static int rank_arr[MAXN];

static int find_set(int v) {
    if (parent[v] != v)
        parent[v] = find_set(parent[v]);
    return parent[v];
}

static void union_set(int a, int b) {
    int ra = find_set(a);
    int rb = find_set(b);
    if (ra == rb) return;
    if (rank_arr[ra] < rank_arr[rb]) {
        parent[ra] = rb;
    } else if (rank_arr[ra] > rank_arr[rb]) {
        parent[rb] = ra;
    } else {
        parent[rb] = ra;
        rank_arr[ra]++;
    }
}

int main(int argc, char **argv) {
    // initialise disjoint set for elements 0..9
    for (int i = 0; i < MAXN; ++i) {
        parent[i] = i;
        rank_arr[i] = 0;
    }

    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    int idx = 1; // start after program name
    while (idx < argc) {
        char *cmd = argv[idx];
        // command must be a single character string
        if (cmd == NULL || cmd[0] == '\0' || cmd[1] != '\0') {
            puts("NOOP");
            return 0;
        }
        if (cmd[0] == 'U') { // UNION a b
            if (idx + 2 >= argc) { puts("INVALID"); return 0; }
            long a = strtol(argv[idx+1], NULL, 10);
            long b = strtol(argv[idx+2], NULL, 10);
            if (a < 0 || a >= MAXN || b < 0 || b >= MAXN) {
                puts("INVALID");
            } else {
                union_set((int)a, (int)b);
                printf("UNION %ld %ld\n", a, b);
            }
            idx += 3;
        } else if (cmd[0] == 'F') { // FIND a
            if (idx + 1 >= argc) { puts("INVALID"); return 0; }
            long a = strtol(argv[idx+1], NULL, 10);
            if (a < 0 || a >= MAXN) {
                puts("INVALID");
            } else {
                int root = find_set((int)a);
                printf("FIND %ld=%d\n", a, root);
            }
            idx += 2;
        } else if (cmd[0] == 'C') { // CONNECT / CHECK a b
            if (idx + 2 >= argc) { puts("INVALID"); return 0; }
            long a = strtol(argv[idx+1], NULL, 10);
            long b = strtol(argv[idx+2], NULL, 10);
            if (a < 0 || a >= MAXN || b < 0 || b >= MAXN) {
                puts("INVALID");
            } else {
                if (find_set((int)a) == find_set((int)b))
                    puts("YES");
                else
                    puts("NO");
            }
            idx += 3;
        } else {
            puts("NOOP");
            return 0;
        }
    }
    return 0;
}
